    "dm": "Наместница Селайн Ко'таллен — тайна вдвойне опаснее, чем была бы у мужчины: по закону Шончан любая женщина, способная направлять, подлежит немедленной поимке и заковыванию в а'дам как дамане — вне зависимости от крови и ранга. Селайн скрывает дар всю жизнь, используя титул Наместницы и Печать как прикрытие; если тайна раскроется, её ждёт не казнь, а цепь — участь, которую она считает страшнее смерти. В бою избегает демонстрировать плетения открыто без крайней необходимости, полагаясь сперва на авторитет ранга и Ауру Имперской Власти.",
